            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = (((aWandererD + RotL64(aCross, 51U)) + RotL64(aCarry, 3U)) + 0xFE10A26AC2D0C668ULL) + aOASaltG[((aIndex + 423U)) & S_SALT1];
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 19U)) + 0x9B7D47BC58A94FA9ULL) + aOASaltD[(((511U - aIndex) + 415U)) & S_SALT1];
            aOrbiterD = (((aWandererG + RotL64(aIngress, 35U)) + RotL64(aCarry, 41U)) + 0xC0CE8171AC6C4CA8ULL) + aOASaltB[(((511U - aIndex) + 45U)) & S_SALT1];
