            aOrbiterB = ((aWandererA + RotL64(aIngress, 42U)) + 0x8A0F3C996C1DD16FULL) + aOASaltE[((aIndex + 492U)) & S_SALT1];
            aOrbiterA = (aWandererJ + RotL64(aScatter, 13U)) + 0x4F8CA06827B34A9FULL;
            aOrbiterJ = (((aWandererI + RotL64(aPrevious, 29U)) + RotL64(aCarry, 21U)) + 0x9415CD56AFE16B60ULL) + aOASaltC[(((511U - aIndex) + 195U)) & S_SALT1];
