            aOrbiterG = ((aWandererF + RotL64(aScatter, 5U)) + 0xDEC631294715E2A8ULL) + aOASaltC[(((511U - aIndex) + 92U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 51U)) + 0xD62A64CCEB665974ULL) + aOASaltB[(((511U - aIndex) + 80U)) & S_SALT1];
            aOrbiterJ = (aWandererK + RotL64(aCross, 21U)) + 0xDE730A89A5E60657ULL;
            aOrbiterC = ((aWandererG + RotL64(aIngress, 35U)) + RotL64(aCarry, 21U)) + 0x20D49C36CA635152ULL;
            aOrbiterI = (aWandererE + RotL64(aPrevious, 60U)) + 0x3439BA678BC8DCF1ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0xD66568811F19872AULL) + aOUSaltD[(((511U - aIndex) + 103U)) & S_SALT1];
