            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x5E521225D7394DC2ULL) + aOUSaltD[(((511U - aIndex) + 387U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xF8F59913286C2074ULL;
