            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x1A3816CA0826FD1AULL) + aOUSaltG[((aIndex + 143U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0x5E34337F542302E2ULL) ^ aOUSaltH[((aIndex + 441U)) & S_SALT1];
