            aWandererG = aWandererG + ((((RotL64(aCross, 23U) + aOrbiterH) + RotL64(aOrbiterE, 35U)) + RotL64(aCarry, 43U)) + aWUSaltE[(((511U - aIndex) + 393U)) & S_SALT1]);
