            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x6DBA63E732828A64ULL) ^ aOUSaltG[(((511U - aIndex) + 268U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x8FD87F49886104C3ULL), 3U);
